          "hindi": "फिर ममतासे आकृष्टचित्त होकर उस आश्रममें इस प्रकार चिन्ता करने लगे-- 'पूर्वकालमें मेरे पूर्वजोंने जिसका पालन किया था, वही नगर आज मुझसे रहित है। पता नहीं, मेरे दुराचारी भृत्यगण उसकी धर्मपूर्वक रक्षा करते हैं या नहीं। जो सदा मदकी वर्षा करनेवाला और शूरवीर था, वह मेरा प्रधान हाथी अब शत्रुओंके अधीन होकर न जाने किन भोगोंको भोगता होगा? जो लोग मेरी कृपा, धन और भोजन पानेसे सदा मेरे पीछे-पीछे चलते थे, वे निश्चय ही अब दूसरे राजाओंका अनुसरण करते होंगे। उन अपव्ययी लोगोंके द्वारा सदा खर्च होते रहनेके कारण अत्यन्त कष्टसे जमा किया हुआ मेरा वह खजाना खाली हो जायगा।' ये तथा और कई बातें राजा सुरथ निरन्तर सोचते रहते थे। एक दिन उन्होंने वहाँ विप्रवर मेधाके आश्रमके निकट एक वैश्यको देखा और उससे पूछा--'भाई! तुम कौन हो? यहाँ तुम्हारे आनेका क्या कारण है? तुम क्यों शोकग्रस्त और अनमने-से दिखायी देते हो?” राजा सुरथका यह प्रेमपूर्वक कहा हुआ वचन सुनकर वैश्यने विनीत-भावसे उन्हें प्रणाम करके कहा--"
