          "hindi": "राजन! वास्तवमें तो वे देवी नित्यस्वरूपा ही हैं। सम्पूर्ण जगत्‌ उन्हींका रूप है तथा उन्होंने समस्त विश्वको व्याप्त कर रखा है, तथापि उनका प्राकट्य अनेक प्रकारसे होता है। वह मुझसे सुनो। यद्यपि वे नित्य और अजन्मा हैं, तथापि जब देवताओंका कार्य सिद्ध करनेके लिये प्रकट होती हैं, उस समय लोकमें उत्पन्न हुई कहलाती हैं। कल्पके अन्तमें जब सम्पूर्ण जगत्‌ एकार्णवमें निमग्न हो रहा था और सबके प्रभु भगवान्‌ विष्णु शेषनागकी शय्या बिछाकर योगनिद्राका आश्रय ले सो रहे थे, उस समय उनके कानोंकी मैलसे दो भयंकर असुर उत्पन्न हुए, जो मधु और कैटभके नामसे विख्यात थे। वे दोनों ब्रह्माजीका वध करनेको तैयार हो गये। भगवान्‌ विष्णुके नाभिकमलमें विराजमान प्रजापति ब्रह्माजीने जब उन दोनों भयानक असुरोंको अपने पास आया और भगवान्‌को सोया हुआ देखा तो एकाग्रचित्त होकर उन्होंने भगवान्‌ विष्णुको जगानेके लिये उनके नेत्रोंमें निवास करनेवाली योगनिद्राका स्तवन आरम्भ किया। जो इस विश्वकी अधीश्वरी, जगत्‌को धारण करनेवाली, संसारका पालन और संहार करनेवाली तथा तेज:स्वरूप भगवान्‌ विष्णुकी अनुपम शक्ति हैं, उन्हीं भगवती निद्रादेवीकी भगवान्‌ ब्रह्मा स्तुति करने लगे"
