          "hindi": "देवि! तुम्हीं स्वाहा, तुम्हीं स्‍्वधा और तुम्हीं वषट्कार हो। स्वर भी तुम्हारे ही स्वरूप हैं। तुम्हीं जीवनदायिनी सुधा हो। नित्य अक्षर प्रणवमें अकार, उकार, मकार--इन तीन मात्राओंके रूपमें तुम्हीं स्थित हो तथा इन तीन मात्राओंके अतिरिक्त जो विन्दुरूपा नित्य अर्धथमात्रा है, जिसका विशेष रूपसे उच्चारण नहीं किया जा सकता, वह भी तुम्हीं हो। देवि! तुम्हीं संध्या, सावित्री तथा परम जननी हो। देवि! तुम्हीं इस विश्व ब्रह्माण्डको धारण करती हो। तुमसे ही इस जगत्‌की सृष्टि होती है। तुम्हींसे इसका पालन होता है और सदा तुम्हीं कल्पके अन्तमें सबको अपना ग्रास बना लेती हो। जगन्मयी देवि! इस जगत्‌की उत्पत्तिके समय तुम सृष्टिरूपा हो, पालन-कालमें स्थितिरूपा हो तथा कल्पान्तके समय संहार-रूप धारण करनेवाली हो। तुम्हीं महाविद्या, महामाया, महामेधा, महास्मृति, महामोह-रूपा, महादेवी और महासुरी हो। तुम्हीं तीनों गुणोंको उत्पन्न करनेवाली सबकी प्रकृति हो। भयंकर कालरात्रि, महारात्रि और मोहरात्रि भी तुम्हीं हो। तुम्हीं श्री, तुम्हीं ईश्वरी, तुम्हीं ही और तुम्हीं बोधस्वरूपा बुद्धि हो। लज्जा, पुष्टि, तुष्टि, शान्ति और क्षमा भी तुम्हीं हो। तुम खड़्गधारिणी, शूलधारिणी, घोररूपा तथा गदा, चक्र, शड्ख और धनुष धारण करनेवाली हो। बाण, भुशुण्डी और परिघ--ये भी तुम्हारे अस्त्र हैं। तुम सौम्य और सौम्यतर हो--इतना ही नहीं, जितने भी सौम्य एवं सुन्दर पदार्थ हैं, उन सबकी अपेक्षा तुम अत्यधिक सुन्दरी हो। पर और अपर--सबसे परे रहनेवाली परमेश्वरी तुम्हीं हो। सर्वस्वरूपे देवि! कहीं भी सत्‌-असत्‌रूप जो कुछ वस्तुएँ हैं और उन सबकी जो शक्ति है, वह तुम्हीं हो। ऐसी अवस्थामें तुम्हारी स्तुति क्या हो सकती है। जो इस जगतकी सृष्टि, पालन और संहार करते हैं, उन भगवान्‌को भी जब तुमने निद्राके अधीन कर दिया है तो तुम्हारी स्तुति करनेमें यहाँ कौन समर्थ हो सकता है। मुझको, भगवान्‌ शंकरको तथा भगवान्‌ विष्णुको भी तुमने ही शरीर धारण कराया है; अतः तुम्हारी स्तुति करनेकी शक्ति किसमें है। देवि! तुम तो अपने इन उदार प्रभावोंसे ही प्रशंसित हो। ये जो दोनों दुर्धर्ष असुर मधु और कैटभ हैं, इनको मोहमें डाल दो और जगदीश्वर भगवान्‌ विष्णुको शीघ्र ही जगा दो। साथ ही इनके भीतर इन दोनों महान्‌ असुरोंको मार डालनेकी बुद्धि उत्पन्न कर दो"
