          "hindi": "राजन! जब ब्रह्माजीने वहाँ मधु और कैटभको मारनेके उद्देश्यसे भगवान्‌ विष्णुको जगानेके लिये तमोगुणकी अधिष्ठात्री देवी योगनिद्राकी इस प्रकार स्तुति की, तब वे भगवानके नेत्र, मुख, नासिका, बाहु, हृदय और वक्ष:स्थलसे निकलकर अव्यक्तजन्मा ब्रह्माजीकी दृष्टिके समक्ष खड़ी हो गयीं। योगनिद्रासे मुक्त होनेपर जगतके स्वामी भगवान्‌ जनार्दन उस एकार्णवके जलमें शेषनागकी शय्यासे जाग उठे। फिर उन्होंने उन दोनों असुरोंको देखा। वे दुरात्मा मधु और कैटभ अत्यन्त बलवान तथा पराक्रमी थे और क्रोधसे लाल आँखें किये ब्रह्माजीको खा जानेके लिये उद्योग कर रहे थे। तब भगवान्‌ श्रीहरिने उठकर उन दोनोंके साथ पाँच हजार वर्षोतक केवल बाहुयुद्ध किया। वे दोनों भी अत्यन्त बलके कारण उन्मत्त हो रहे थे। इधर महामायाने भी उन्हें मोहमें डाल रखा था; इसलिये वे भगवान्‌ विष्णुसे कहने लगे--“हम तुम्हारी वीरतासे संतुष्ट हैं। तुम हमलोगोंसे कोई वर माँगो”"
