          "keywords": [],
          "hindi": "धनाध्यक्ष कुबेरने मधुसे भरा पानपात्र दिया तथा सम्पूर्ण नागोंके राजा शेषने, जो इस पृथ्वीको धारण करते हैं, उन्हें बहुमूल्य मणियोंसे विभूषित नागहार भेंट दिया। इसी प्रकार अन्य देवताओंने भी आभूषण और अस्त्र-शस्त्र देकर देवीका सम्मान किया। तत्पश्चात्‌ उन्होंने बारंबार अट्टहासपूर्वक उच्चस्वरसे गर्जना की। उनके भयंकर नादसे सम्पूर्ण आकाश गूँज उठा"
