          "transliteration": "durge smṛtā harasi bhītimśeṣajantoḥ svasthaiḥ smṛtā matimatīva śubhāṃ dadāsi | dāridryaduḥkhabhayahāriṇi kā tvadanyā sarvopakārakaraṇāya sadā'rdracittā ||",
          "translation": "O Durga, when remembered by those in distress, you remove fear from all beings; when remembered by those who are well, you give them wisdom of the highest auspiciousness. Who other than you, O remover of poverty, sorrow, and fear — has a heart ever moist with compassion for the welfare of all?",
          "hindi": "हे दुर्गे! संकट में स्मरण करने पर तुम सभी प्राणियों का भय हर लेती हो; स्वस्थ अवस्था में स्मरण करने पर उत्कृष्ट शुभ बुद्धि देती हो। हे दारिद्र्य-दुःख-भय-हारिणी! सबके उपकार के लिए सदा आर्द्र चित्त वाली तुम्हारे सिवाय और कौन है?",
          "explanation": "Mahishasura — the buffalo-demon — is tamas embodied: the heavy, dark, stubborn inertia that refuses to yield to light. But this verse reveals why the Devi's victory matters: she is not merely a warrior. She is \"sadā ārdrа-cittā\" — always soft-hearted, ever moist with compassion. The fierceness that slays Mahishasura and the tenderness that weeps for suffering are one and the same being. Durga integrates what we typically split: strength and softness, ferocity and compassion.",
          "science": "Research on \"tender-minded vs. tough-minded\" leadership (James MacGregor Burns): the most effective transformational leaders combine high challenge (demanding excellence, confronting hard truths) with high support (genuine care, emotional warmth). Neither alone produces transformation. The Devi's combination of fierce demon-slaying and \"ārdra citta\" (moist compassion) is the mythic template of this paradox.",
          "lifeLesson": "Where in your life do you split strength from softness — believing you must choose between being fierce and being kind? The Devi says: the highest form of each requires the other. Your compassion without fierceness is sentimentality; your fierceness without compassion is cruelty. Cultivate both, simultaneously. That integration is Durga.",
