          "transliteration": "devyA yayA tatamidaM jagadAtmashaktyA niHsheShadevagaNashaktisamUhamUrtyA | tAmambikAmakhiladevamaharShipUjyAM bhaktyA natAH sma vidadhAtu shubhAni sA naH",
