          "keywords": [],
          "hindi": "ऋषिरुवाच ।/ ३८ ॥। इति प्रसादिता देवैर्जगतो<रथें तथा55त्मन: । तथेत्युक्त्वा भद्रकाली बभूवान्तर्हिता नूप"
