          "hindi": "कौमारीकी शक्तिसे विदीर्ण होकर कितने ही महादैत्य नष्ट हो गये। ब्रह्माणीके मन्त्रपूत जलसे निस्तेज होकर कितने ही भाग खड़े हुए"
