          "transliteration": "devi prapannArtihare prasIda prasIda mAtarjagato.akhilasya | prasIda vishveshvari pAhi vishvaM tvamIshvarI devi charAcharasya",
          "translation": "In this manner, whenever there shall be trouble arising from the demonic forces, I shall descend each time and destroy the enemies.",
          "hindi": "इस प्रकार जब-जब भी दैत्यों से उत्पन्न बाधा होगी, तब-तब मैं अवतरित होकर शत्रुओं का संहार करूँगी।",
